# -*- coding: utf-8 -*-
"""
PEREVOZKA_TUDA_OBRATNO (12.11) — перевозка в обе стороны, квартира остаётся за жителем.

СЛОВО ШЕФА 11.11: «мы же вроде в жильё их транспортируем? житель с собой заберёт
    с города, а квартира его остаётся, он вернуться может… а так он совсем исчезнет
    из города — бесследно?» → «да» (дорога в обе стороны; на острове — до причала,
    дальше прописка и работа руками Шефа).

ЧТО СТАВИТ (на том берегу, где запущен — материк или остров одинаково)
    1. ГОРОД/propiska.py — вторая версия: пропуск выдаёт ГОРОД, ГДЕ ЖИТЕЛЬ
       ПРОПИСАН (не только материк) — значит, можно и домой; «копия» в словах
       стала «уехал(а) туда-то — дом и жильё ждут». Реестр и рейсы не трогаются.
    2. perevozka.py — третья версия: меню «1. Отправить · 2. Принять» на обоих
       берегах; с материка по умолчанию на «I1», с острова — домой на «T1»;
       принятый житель остаётся НА ПРИЧАЛЕ — дальше ПРОПИСКА (жильё) и РАБОТА
       руками Шефа; вернувшийся домой встаёт в свою квартиру, прежняя папка
       откладывается рядом.
    Прежние версии — рядом: .bak_tuda_obratno.

КАК ЗАПУСКАТЬ: класть в корень (материка или острова), запускать как обычно.
    Ставить на ОБОИХ берегах.
"""
import sys
import py_compile
import shutil
from pathlib import Path

PROPISKA = '# -*- coding: utf-8 -*-\n# PROPISKA_MIRA_V1 · V2 (дорога в обе стороны) — прописка: признаёт ли этот мир единицу\n"""\nПРОПИСКА · одно место на весь мир\n\nСлово Шефа 11.11: «нужен ключ идентификации, чтобы дубли не плодились: он\nединый, даже если дубль сделать — его город и мир не примет»; «сделай эту\nпроверку так, чтобы она встраивалась в будущем в нужные места — будут и\nлокации, и ещё много чего, чтобы не забыть».\n\nЗАКОН ПРОПИСКИ\n    Ключ единицы — отпечаток её печати создателя (_Creator_Seal_Hash), он\n    рождается на Странице Жизни главного города и не меняется никогда.\n    Скопировать папку можно всегда — но мир признаёт единицу только там,\n    где она ПРОПИСАНА. Копия с тем же ключом в другом месте — не признаётся:\n    её не будят, не сажают, ею не работают.\n\n    ЛЮБОЕ место кода, которое берёт единицу ДЛЯ ДЕЛА (будит, сажает на пост,\n    ведёт в работу, везёт), спрашивает:\n\n        import propiska\n        ok, pochemu = propiska.priznan(dom=папка)        # или klyuch=..., imya=...\n        if not ok: ...  # не работать с ней, сказать почему\n\n    Новый вид единицы (инструмент, посылка, здание…) — новая строка в ВИДЫ,\n    код проверки не трогаем. Строгость вида — там же: строгий вид без\n    прописки не признаётся; нестрогий — прописывается при первой встрече\n    (так мягко входят виды, пока у них нет перевозки).\n\n    Чтобы не забыть: propiska.audit_koda() показывает места кода, которые\n    берут жителей и локации, но ещё не спрашивают прописку.\n\nГДЕ ЧТО ЛЕЖИТ (GRONDHEIM_CITY/мир/)\n    город.json      — кто этот город: {"id": "T1", "имя": ..., "материк": true}\n    прописка.json   — реестр: ключ → {вид, имя, id, где, дом, с, рейс}\n                      На материке реестр — главный. На острове — свой список\n                      тех, кого он принял по пропускам.\n    рейсы.json      — пропуска, уже принятые этим городом (второй раз — нет)\n\nПЕЧАТЬ ГОРОДА — одна секретная фраза мира, только в .env обеих машин:\n    GRONDHEIM_PECHAT_GORODA=...\n    Ею заверяется пропуск рейса. В репо её нет и быть не должно.\n"""\nfrom __future__ import annotations\n\nimport hashlib\nimport hmac\nimport json\nimport os\nimport re\nimport secrets\nfrom datetime import datetime\nfrom pathlib import Path\n\n_HERE = Path(__file__).resolve().parent          # ГОРОД/\nKOREN = _HERE.parent\nCITY = KOREN / "GRONDHEIM_CITY"\nMIR = CITY / "мир"\nGOROD_F = MIR / "город.json"\nREESTR_F = MIR / "прописка.json"\nREYSY_F = MIR / "рейсы.json"\nPOLE_KLYUCHA = "_Creator_Seal_Hash"\nENV_PECHAT = "GRONDHEIM_PECHAT_GORODA"\n\n# Виды единиц мира. Новый вид — новая строка, проверку не трогаем.\nVIDY = {\n    "житель":  {"папка": CITY / "жители" / "ковчег", "паспорт": "passport.json",\n                "строго": True},\n    "локация": {"папка": CITY / "локации", "паспорт": "passport.json",\n                "строго": False},\n}\n\n\n# ── диск ───────────────────────────────────────────────────────\ndef _chitat(p: Path, default=None):\n    for kod in ("utf-8", "utf-8-sig"):\n        try:\n            return json.loads(p.read_text(encoding=kod))\n        except Exception:\n            continue\n    return default\n\n\ndef _pisat(p: Path, d) -> None:\n    p.parent.mkdir(parents=True, exist_ok=True)\n    tmp = p.with_suffix(p.suffix + ".tmp")\n    tmp.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")\n    tmp.replace(p)\n\n\ndef _teper() -> str:\n    return datetime.now().strftime("%Y-%m-%d %H:%M")\n\n\n# ── кто этот город ─────────────────────────────────────────────\ndef gorod() -> dict:\n    g = _chitat(GOROD_F, None)\n    if g:\n        return g\n    # Не задан — материк узнаём по Странице Жизни: она только там.\n    materik = (KOREN / "Брат" / "ui_registry.py").is_file()\n    return {"id": "T1" if materik else "?", "имя": "Грондхейм" if materik else "",\n            "материк": materik, "_note": "не задан явно — определён по Странице Жизни"}\n\n\ndef gorod_id() -> str:\n    return str(gorod().get("id") or "?")\n\n\ndef eto_materik() -> bool:\n    return bool(gorod().get("материк"))\n\n\n# ── реестр ─────────────────────────────────────────────────────\ndef reestr() -> dict:\n    return _chitat(REESTR_F, None) or {"записи": {}}\n\n\ndef zapis(klyuch: str) -> dict:\n    return (reestr().get("записи") or {}).get(klyuch or "", {}) or {}\n\n\ndef _sohranit_zapis(klyuch: str, z: dict) -> None:\n    r = reestr()\n    r.setdefault("записи", {})[klyuch] = z\n    r["_note"] = ("Мировой реестр прописки: ключ единицы → где она живёт. Закон — "\n                  "ГОРОД/propiska.py. Копия с тем же ключом в другом месте не признаётся.")\n    _pisat(REESTR_F, r)\n\n\n# ── ключ и дом единицы ─────────────────────────────────────────\ndef klyuch_doma(dom: Path, vid: str = "житель") -> str:\n    p = _chitat(Path(dom) / VIDY.get(vid, VIDY["житель"])["паспорт"], {}) or {}\n    return str(p.get(POLE_KLYUCHA) or "").strip()\n\n\ndef doma(vid: str = "житель") -> list:\n    """[(дом, паспорт, ключ)] всех единиц вида в этом городе."""\n    v = VIDY.get(vid)\n    if not v or not v["папка"].is_dir():\n        return []\n    out = []\n    for d in sorted(v["папка"].iterdir()):\n        if not d.is_dir():\n            continue\n        p = _chitat(d / v["паспорт"], None)\n        if p is None:\n            continue\n        out.append((d, p, str(p.get(POLE_KLYUCHA) or "").strip()))\n    return out\n\n\ndef dom_po_imeni(imya: str, vid: str = "житель"):\n    for d, p, _k in doma(vid):\n        if imya in ((p.get("Official_Name") or "").strip(), d.name):\n            return d\n    return None\n\n\n# ── ГЛАВНОЕ: признан ли ────────────────────────────────────────\ndef priznan(klyuch: str = "", *, dom=None, imya: str = "", vid: str = "житель") -> tuple:\n    """(True/False, почему). Спрашивать перед любым ДЕЛОМ с единицей."""\n    try:\n        if dom is None and imya:\n            dom = dom_po_imeni(imya, vid)\n        if not klyuch and dom is not None:\n            klyuch = klyuch_doma(dom, vid)\n        if not klyuch:\n            return True, "без ключа — старый порядок (печати нет)"\n        z = zapis(klyuch)\n        gid = gorod_id()\n        strogo = VIDY.get(vid, {}).get("строго", True)\n        if not z:\n            if eto_materik() or not strogo:\n                imya_ = imya or (dom.name if dom is not None else "")\n                _sohranit_zapis(klyuch, {"вид": vid, "имя": imya_, "где": gid,\n                                         "дом": dom.name if dom is not None else "",\n                                         "с": _teper(), "рейс": "",\n                                         "_как": "прописан при первой встрече"})\n                return True, f"прописан здесь ({gid}) при первой встрече"\n            return False, (f"в этом городе ({gid}) не прописан — приехать можно только "\n                           "по пропуску перевозки")\n        if str(z.get("где")) != gid:\n            return False, (f"уехал(а) в «{z.get(\'где\')}» с {z.get(\'с\', \'?\')}"\n                           + (f", рейс {z.get(\'рейс\')}" if z.get("рейс") else "")\n                           + " — здесь его нет: дом и жильё ждут, на работу не встаёт")\n        if dom is not None and z.get("дом") and z.get("дом") != dom.name:\n            return False, f"двойник: настоящий дом этого ключа — «{z.get(\'дом\')}»"\n        return True, f"прописан здесь ({gid})"\n    except Exception as e:\n        # Проверка сама не должна ронять город: честно говорим и пропускаем.\n        print(f"[ПРОПИСКА] проверка не сложилась ({e}) — пропускаю")\n        return True, f"проверка не сложилась: {e}"\n\n\ndef priznan_li(**kw) -> bool:\n    return priznan(**kw)[0]\n\n\n# ── первая перепись (материк) ──────────────────────────────────\ndef pervaya_perepis() -> dict:\n    """Все единицы в этом городе с ключом и без записи — прописываются здесь.\n    Двойники (два дома с одним ключом) — в отчёт, без записи второго."""\n    gid = gorod_id()\n    itog = {"прописано": 0, "уже": 0, "без_ключа": [], "двойники": []}\n    for vid in VIDY:\n        vidno = {}\n        for d, p, k in doma(vid):\n            if not k:\n                itog["без_ключа"].append(f"{vid}: {d.name}")\n                continue\n            if k in vidno:\n                itog["двойники"].append(f"{vid}: {d.name} = {vidno[k]}")\n                continue\n            vidno[k] = d.name\n            if zapis(k):\n                itog["уже"] += 1\n                continue\n            _sohranit_zapis(k, {"вид": vid, "имя": (p.get("Official_Name") or d.name),\n                                "id": p.get("ID_Object", ""), "где": gid, "дом": d.name,\n                                "с": _teper(), "рейс": "", "_как": "первая перепись"})\n            itog["прописано"] += 1\n    return itog\n\n\n# ── печать города и пропуск рейса ──────────────────────────────\ndef _pechat() -> bytes:\n    f = os.getenv(ENV_PECHAT, "")\n    if not f:\n        env = KOREN / ".env"\n        if env.is_file():\n            for s in env.read_text(encoding="utf-8", errors="replace").splitlines():\n                s = s.strip()\n                if s.startswith(ENV_PECHAT + "="):\n                    f = s.split("=", 1)[1].strip().strip(\'"\').strip("\'")\n                    break\n    return f.encode("utf-8")\n\n\ndef est_pechat() -> bool:\n    return bool(_pechat())\n\n\ndef _podpis(telo: dict) -> str:\n    stroka = json.dumps(telo, ensure_ascii=False, sort_keys=True)\n    return hmac.new(_pechat(), stroka.encode("utf-8"), hashlib.sha256).hexdigest()\n\n\ndef vydat_propusk(klyuch: str, kuda: str, imya: str = "", vid: str = "житель") -> dict:\n    """Город, где единица прописана, переписывает прописку на «куда» и выдаёт\n    заверенный пропуск. Дорога в обе стороны: с материка на остров и обратно.\n    С этой секунды здесь единицы нет — дом и жильё ждут её возвращения."""\n    if not est_pechat():\n        raise RuntimeError(f"нет печати города — впиши {ENV_PECHAT}=… в .env")\n    if str(kuda) == gorod_id():\n        raise RuntimeError("пропуск в свой же город не выдаётся")\n    z = zapis(klyuch)\n    if z and str(z.get("где")) != gorod_id():\n        raise RuntimeError(f"сейчас прописан(а) в «{z.get(\'где\')}» — отправлять отсюда нечего")\n    if not z and not eto_materik():\n        raise RuntimeError("в этом городе не прописан(а) — отправить нельзя")\n    reys = f"{datetime.now():%Y%m%d%H%M}-{secrets.token_hex(3)}"\n    telo = {"рейс": reys, "ключ": klyuch, "вид": vid, "имя": imya,\n            "откуда": gorod_id(), "куда": kuda, "когда": _teper()}\n    propusk = dict(telo, подпись=_podpis(telo))\n    novaya = dict(z or {}, вид=vid, имя=imya or (z or {}).get("имя", ""), где=kuda,\n                  с=_teper(), рейс=reys, дом=(z or {}).get("дом", ""), _как="уехал по пропуску")\n    _sohranit_zapis(klyuch, novaya)\n    return propusk\n\n\ndef prinyat_propusk(propusk: dict, dom_imya: str = "") -> tuple:\n    """Город прибытия: печать верна, пропуск сюда и ещё не использован →\n    единица прописывается здесь. (True/False, почему)."""\n    if not est_pechat():\n        return False, f"нет печати города — впиши {ENV_PECHAT}=… в .env"\n    telo = {k: v for k, v in (propusk or {}).items() if k != "подпись"}\n    if not hmac.compare_digest(_podpis(telo), str((propusk or {}).get("подпись", ""))):\n        return False, "печать пропуска не сходится — пропуск поддельный или печати разные"\n    if str(telo.get("куда")) != gorod_id():\n        return False, f"пропуск не сюда: он в «{telo.get(\'куда\')}», а это «{gorod_id()}»"\n    ispolz = _chitat(REYSY_F, None) or {"рейсы": {}}\n    if telo.get("рейс") in (ispolz.get("рейсы") or {}):\n        return False, f"рейс {telo.get(\'рейс\')} уже принят — второй экземпляр не признаётся"\n    ispolz.setdefault("рейсы", {})[telo["рейс"]] = {"ключ": telo.get("ключ"),\n                                                   "имя": telo.get("имя"), "принят": _teper()}\n    _pisat(REYSY_F, ispolz)\n    _sohranit_zapis(telo["ключ"], {"вид": telo.get("вид", "житель"), "имя": telo.get("имя", ""),\n                                   "где": gorod_id(), "дом": dom_imya or telo.get("имя", ""),\n                                   "с": _teper(), "рейс": telo.get("рейс"),\n                                   "_как": f"приехал из «{telo.get(\'откуда\')}»"})\n    return True, f"принят по пропуску рейса {telo.get(\'рейс\')}"\n\n\n# ── чтобы не забыть: где код берёт единицы без проверки ────────\n_PRIMETY = (re.compile(r"ковчег"), re.compile(r"passport\\.json"), re.compile(r"локации"))\n_NE_SMOTRET = {".git", "__pycache__", "_ЧУЛАН", "_ПЕЧАТИ", "_ПЕРЕЕЗД", "node_modules",\n               "venv", ".venv", "замеры"}\n\n\ndef audit_koda(koren: Path = None) -> list:\n    """[(файл, сколько примет)] — модули, которые берут жителей или локации,\n    но ещё не спрашивают прописку. Патчи и замеры не смотрим."""\n    koren = koren or KOREN\n    out = []\n    for p in koren.rglob("*.py"):\n        otn = p.relative_to(koren)\n        if any(x in _NE_SMOTRET for x in otn.parts) or ".bak" in p.name:\n            continue\n        if len(otn.parts) == 1:          # корень — это патчи и замеры\n            continue\n        try:\n            t = p.read_text(encoding="utf-8", errors="replace")\n        except Exception:\n            continue\n        if "propiska" in t or p.name == "propiska.py":\n            continue\n        n = sum(len(rx.findall(t)) for rx in _PRIMETY)\n        if n:\n            out.append((otn.as_posix(), n))\n    return sorted(out, key=lambda x: -x[1])\n\n\n# PROPISKA_MIRA_V1 - marker\n# PROPISKA_MIRA_V2 - marker\n'

PEREVOZKA = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n# PEREVOZKA_ZHITELYA_V3\n"""\nПЕРЕВОЗКА ЖИТЕЛЯ · с ключом, в обе стороны. Один файл на оба берега.\n\nСлово Шефа 29.09 и 11.11: житель едет ВЕСЬ — с лицом и со всей памятью,\nвключая рабочий след; квартира в городе остаётся за ним, он может вернуться;\nу жителя один ключ, и прописан он ровно в одном месте; на причале — сверка.\n\n    ОТПРАВИТЬ (любой берег, где житель прописан):\n        1. снимается с места (работы);\n        2. пакуется ВЕСЬ дом: паспорт, лицо, маски, память, опыт, работа,\n           чаты — кроме служебного мусора и видео/звука; фразы печати нет;\n        3. у каждого файла — отпечаток;\n        4. город переписывает прописку на место прибытия и кладёт в архив\n           ПРОПУСК РЕЙСА, заверенный печатью города.\n        Дом и жильё здесь ОСТАЮТСЯ: в паспорте отметка «уехал(а) туда-то,\n        рейс такой-то». Пока его нет — не будят и не сажают на работу.\n\n    ПРИНЯТЬ (берег прибытия):\n        1. сверка отпечатков; 2. сверка печати пропуска и что рейс новый;\n        3. житель — на ПРИЧАЛ (ковчег), прописан здесь. Если здесь был его\n           прежний дом (возвращение) — прежняя папка откладывается рядом,\n           житель возвращается в свою квартиру со всем, что прожил;\n        4. дальше — твоими руками, по трём ступеням: ЕСТЬ (причал) →\n           ЖИВЁТ (ПРОПИСКА в жильё: жильё квартала + его слова) → РАБОТАЕТ (пост).\n        Не сошлось — не принимается, архив уходит в _ПРИБЫТИЕ/отказ.\n\nАрхивом, а не по сети: берега — разные машины. Архив переносится как угодно.\n"""\nimport argparse\nimport hashlib\nimport json\nimport shutil\nimport sys\nimport tempfile\nimport zipfile\nfrom datetime import datetime\nfrom pathlib import Path\n\nif sys.platform == "win32":\n    try:\n        sys.stdout.reconfigure(encoding="utf-8")\n    except Exception:\n        pass\n\nKOREN = Path(__file__).resolve().parent\nCITY = KOREN / "GRONDHEIM_CITY"\nKOVCHEG = CITY / "жители" / "ковчег"\nOTPRAVKA = KOREN / "_ОТПРАВКА"\nPRIBYTIE = KOREN / "_ПРИБЫТИЕ"\n\nNE_VEZYOM_PAPKI = {"__pycache__", ".git"}\nNE_VEZYOM_RASSH = {".mp3", ".mp4", ".wav", ".mov", ".avi", ".zip", ".pyc", ".tmp"}\nSEKRET = "Creator_Seal"          # фраза печати — никогда не едет\nKUDA_PO_UMOLCHANIYU = ""            # пусто — с материка на «I1», с острова домой на «T1»\n\n\ndef skazat(s=""):\n    print(s, flush=True)\n\n\ndef cherta():\n    skazat("=" * 62)\n\n\ndef _sprosit(vopros: str) -> str:\n    try:\n        return input(vopros).strip()\n    except Exception:\n        return ""\n\n\ndef _put_goroda():\n    for p in (KOREN / "ГОРОД",):\n        if str(p) not in sys.path:\n            sys.path.insert(0, str(p))\n\n\ndef _propiska():\n    _put_goroda()\n    try:\n        import propiska\n        return propiska\n    except Exception as e:\n        skazat(f"  x закона прописки нет ({e}) — сначала propiska_mira.py / переселение")\n        return None\n\n\ndef _rabota():\n    _put_goroda()\n    try:\n        import rabota\n        return rabota\n    except Exception as e:\n        skazat(f"  (механизм работы не поднялся: {e})")\n        return None\n\n\ndef eto_ostrov() -> bool:\n    pr = _propiska()\n    if pr is not None:\n        try:\n            return not pr.eto_materik()\n        except Exception:\n            pass\n    return (KOREN / "ostrov_puls.py").is_file() or (KOREN / "OSTROV_NADEZHDY.md").is_file()\n\n\ndef _otpechatok(data: bytes) -> str:\n    return hashlib.sha256(data).hexdigest()\n\n\ndef _bez_sekreta(otn: Path, data: bytes) -> bytes:\n    """Из json-файлов убираем фразу печати, если где-то осталась."""\n    if otn.suffix.lower() != ".json" or SEKRET.encode() not in data:\n        return data\n    try:\n        d = json.loads(data.decode("utf-8"))\n    except Exception:\n        return data\n\n    def chistit(x):\n        if isinstance(x, dict):\n            x.pop(SEKRET, None)\n            for v in x.values():\n                chistit(v)\n        elif isinstance(x, list):\n            for v in x:\n                chistit(v)\n    chistit(d)\n    return json.dumps(d, ensure_ascii=False, indent=2).encode("utf-8")\n\n\n# ══════════════════════════════════════════════════════════════\n# ОТПРАВИТЕЛЬ — материк\n# ══════════════════════════════════════════════════════════════\n\ndef zhiteli() -> list:\n    out = []\n    if not KOVCHEG.is_dir():\n        return out\n    pr = _propiska()\n    for d in sorted(KOVCHEG.iterdir()):\n        if not d.is_dir():\n            continue\n        p = d / "passport.json"\n        imya, rabota_gde, klyuch = d.name, "", ""\n        if p.is_file():\n            try:\n                dd = json.loads(p.read_text(encoding="utf-8"))\n                imya = dd.get("Official_Name", d.name)\n                klyuch = str(dd.get("_Creator_Seal_Hash") or "")\n                r = dd.get("Работа") or {}\n                rabota_gde = r.get("должность", "") or r.get("где", "")\n            except Exception:\n                pass\n        priznan, pochemu = (True, "")\n        if pr is not None:\n            priznan, pochemu = pr.priznan(dom=d)\n        out.append({"имя": imya, "папка": d, "работа": rabota_gde, "ключ": klyuch,\n                    "признан": priznan, "почему": pochemu})\n    return out\n\n\ndef _post_zhitelya(R, imya: str):\n    if R is None:\n        return None\n    try:\n        for m in R.mesta():\n            if m.get("кто_сидит") == imya:\n                return m["id"]\n    except Exception:\n        pass\n    return None\n\n\ndef _kuda_po_umolchaniyu() -> str:\n    pr = _propiska()\n    try:\n        return "I1" if (pr is None or pr.eto_materik()) else "T1"\n    except Exception:\n        return "I1"\n\n\ndef upakovat(chelovek: dict, R, kuda: str = KUDA_PO_UMOLCHANIYU):\n    kuda = kuda or _kuda_po_umolchaniyu()\n    imya, dom = chelovek["имя"], chelovek["папка"]\n    pr = _propiska()\n    if pr is None:\n        return None\n    if not chelovek.get("ключ"):\n        skazat("  x у жителя нет ключа (печати) — с ключом рождают на Странице Жизни")\n        return None\n    if not chelovek.get("признан", True):\n        skazat(f"  x не отправляю: {chelovek.get(\'почему\')}")\n        return None\n    if not pr.est_pechat():\n        skazat(f"  x нет печати города — впиши {pr.ENV_PECHAT}=… в .env")\n        return None\n\n    post = _post_zhitelya(R, imya)\n    if post:\n        ok, msg = R.uvolit(post, pochemu="переезд на остров")\n        skazat(f"  снят с места: {msg}" if ok else f"  ! снять не вышло: {msg}")\n\n    fajly, n_bajt = {}, 0\n    OTPRAVKA.mkdir(exist_ok=True)\n    arhiv = OTPRAVKA / f"{imya}_{datetime.now():%Y%m%d_%H%M}.zip"\n    with zipfile.ZipFile(arhiv, "w", zipfile.ZIP_DEFLATED) as z:\n        for p in sorted(dom.rglob("*")):\n            if not p.is_file():\n                continue\n            otn = p.relative_to(dom)\n            if any(x in NE_VEZYOM_PAPKI for x in otn.parts):\n                continue\n            if p.suffix.lower() in NE_VEZYOM_RASSH or ".bak" in p.name:\n                continue\n            data = _bez_sekreta(otn, p.read_bytes())\n            imya_v = str(Path(imya) / otn).replace("\\\\", "/")\n            z.writestr(imya_v, data)\n            fajly[imya_v] = _otpechatok(data)\n            n_bajt += len(data)\n        # пропуск — последним: с этой секунды прописка уже на острове\n        try:\n            propusk = pr.vydat_propusk(chelovek["ключ"], kuda, imya)\n        except Exception as e:\n            z.close()\n            arhiv.unlink(missing_ok=True)\n            skazat(f"  x пропуск не выдан: {e} — ничего не отправлено")\n            return None\n        z.writestr("_ПРОПУСК.json", json.dumps(propusk, ensure_ascii=False, indent=2))\n        z.writestr("_ПЕРЕВОЗКА.json", json.dumps({\n            "имя": imya, "когда": datetime.now().isoformat(timespec="seconds"),\n            "откуда": pr.gorod_id(), "куда": kuda, "рейс": propusk["рейс"],\n            "файлов": len(fajly), "отпечатки": fajly,\n            "_note": "житель целиком: паспорт, лицо, маски, память, опыт, работа. "\n                     "Фразы печати в архиве нет."}, ensure_ascii=False, indent=2))\n    # отметка на материковой копии — видно, что житель уехал\n    try:\n        pp = dom / "passport.json"\n        d = json.loads(pp.read_text(encoding="utf-8"))\n        d["_уехал"] = {"куда": kuda, "рейс": propusk["рейс"],\n                       "когда": datetime.now().isoformat(timespec="seconds"),\n                       "_note": "уехал(а); дом и жильё здесь остаются за жителем. Пока "\n                                "его нет — не будят и не сажают на работу. Вернётся — "\n                                "перевозкой обратно, в эту же квартиру."}\n        pp.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")\n    except Exception:\n        pass\n    skazat(f"  упаковано файлов: {len(fajly)} ({n_bajt / 1024 / 1024:.1f} МБ), "\n           f"рейс {propusk[\'рейс\']} → {kuda}")\n    return arhiv\n\n\ndef otpravitel(kuda: str = KUDA_PO_UMOLCHANIYU) -> int:\n    kuda = kuda or _kuda_po_umolchaniyu()\n    lyudi = [ch for ch in zhiteli() if ch["признан"]]\n    if not lyudi:\n        skazat("  жителей не нашёл — это точно материк?")\n        return 1\n    R = _rabota()\n    skazat(f"\\nКого отправляем в «{kuda}»?\\n")\n    for i, ch in enumerate(lyudi, 1):\n        gde = ch["работа"] or "— без места —"\n        skazat(f"   {i:>2}. {ch[\'имя\']:<16} {gde}")\n    skazat("\\n   можно несколько через запятую · Enter — отмена")\n    otvet = _sprosit("\\n> ")\n    if not otvet:\n        skazat("отменил")\n        return 0\n    nomera = [int(k) for k in otvet.replace(" ", "").split(",")\n              if k.isdigit() and 1 <= int(k) <= len(lyudi)]\n    if not nomera:\n        skazat("не понял, кого — отменил")\n        return 0\n    skazat("")\n    arhivy = []\n    for n in nomera:\n        ch = lyudi[n - 1]\n        skazat(f"— {ch[\'имя\']}")\n        a = upakovat(ch, R, kuda)\n        if a:\n            arhivy.append(a)\n            skazat(f"  готово: {a.relative_to(KOREN)}")\n    cherta()\n    skazat(f"Собрано архивов: {len(arhivy)} — в папке {OTPRAVKA.name}")\n    skazat(f"Перенеси архив(ы) в «{kuda}» (флешка, облако, RDP) — в корень того города —")\n    skazat("и запусти там перевозку: «принять».")\n    skazat("Дом и жильё здесь остаются за жителем; пока его нет — на работу его не зовут.")\n    return 0\n\n\n# ══════════════════════════════════════════════════════════════\n# ПОЛУЧАТЕЛЬ — остров\n# ══════════════════════════════════════════════════════════════\n\ndef nayti_arhivy() -> list:\n    out = []\n    for d in (KOREN, PRIBYTIE):            # своё исходящее (_ОТПРАВКА) не принимаем\n        if not d.is_dir():\n            continue\n        for p in sorted(d.glob("*.zip")):\n            try:\n                with zipfile.ZipFile(p) as z:\n                    if "_ПЕРЕВОЗКА.json" in z.namelist():\n                        out.append(p)\n            except Exception:\n                continue\n    return out\n\n\ndef _gorod_ostrova():\n    """На острове без мир/город.json — заводим «I1»."""\n    gf = CITY / "мир" / "город.json"\n    if gf.is_file():\n        return\n    if (KOREN / "Брат" / "ui_registry.py").is_file():\n        return                       # это материк — не трогаем\n    gf.parent.mkdir(parents=True, exist_ok=True)\n    gf.write_text(json.dumps({"id": "I1", "имя": "Остров Надежды", "материк": False},\n                             ensure_ascii=False, indent=2), encoding="utf-8")\n    skazat("  (мир/город.json не было — этот город записан как «I1», Остров Надежды)")\n\n\ndef raspakovat(arhiv: Path):\n    pr = _propiska()\n    if pr is None:\n        return None\n    with zipfile.ZipFile(arhiv) as z:\n        imena = z.namelist()\n        try:\n            karta = json.loads(z.read("_ПЕРЕВОЗКА.json").decode("utf-8"))\n        except Exception:\n            skazat(f"  x {arhiv.name}: это не архив перевозки")\n            return None\n        imya = (karta.get("имя") or "").strip()\n        if "_ПРОПУСК.json" not in imena or not karta.get("отпечатки"):\n            skazat(f"  x {arhiv.name}: архив старой перевозки — без пропуска и отпечатков. "\n                   "Не принимаю: отправь жителя заново новой перевозкой.")\n            return None\n        # 1. отпечатки\n        plohie = [i for i, o in karta["отпечатки"].items()\n                  if i not in imena or _otpechatok(z.read(i)) != o]\n        lishnie = [i for i in imena if i not in karta["отпечатки"]\n                   and i not in ("_ПЕРЕВОЗКА.json", "_ПРОПУСК.json")]\n        if plohie or lishnie:\n            skazat(f"  x {imya}: архив повреждён или подменён (не сошлось: {len(plohie)}, "\n                   f"лишних: {len(lishnie)}) — не принимаю")\n            return None\n        skazat(f"  отпечатки сошлись: {len(karta[\'отпечатки\'])} файлов")\n        # 2. распаковать во временное место, проверить пропуск, потом — в ковчег\n        propusk = json.loads(z.read("_ПРОПУСК.json").decode("utf-8"))\n        with tempfile.TemporaryDirectory() as tmp:\n            for i in karta["отпечатки"]:\n                z.extract(i, tmp)\n            ok, pochemu = pr.prinyat_propusk(propusk, dom_imya=imya)\n            if not ok:\n                skazat(f"  x {imya}: {pochemu}")\n                return None\n            skazat(f"  пропуск: {pochemu}")\n            KOVCHEG.mkdir(parents=True, exist_ok=True)\n            dom = KOVCHEG / imya\n            if dom.exists():\n                zapas = KOVCHEG / f"_{imya}_было_{datetime.now():%Y%m%d_%H%M}"\n                dom.replace(zapas)\n                skazat(f"  вернулся(ась) домой: прежняя папка отложена как {zapas.name}")\n            shutil.move(str(Path(tmp) / imya), str(dom))\n        # снять отметку «уехал» — здесь он дома\n        try:\n            pp = dom / "passport.json"\n            d = json.loads(pp.read_text(encoding="utf-8"))\n            d.pop("_уехал", None)\n            d.pop("Работа", None)\n            d["_приехал"] = {"откуда": karta.get("откуда"), "рейс": propusk.get("рейс"),\n                             "когда": datetime.now().isoformat(timespec="seconds")}\n            pp.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")\n        except Exception:\n            pass\n        skazat(f"  {imya}: на причале (ковчег), прописан здесь")\n    return imya\n\n\ndef posadit(R, imya: str):\n    if R is None:\n        return\n    try:\n        svobodnye = [m for m in R.mesta() if m.get("есть_пост") and not m.get("кто_сидит")]\n    except Exception as e:\n        skazat(f"  (мест не вижу: {e})")\n        return\n    if not svobodnye:\n        skazat("  свободных мест нет — посадишь позже на странице работы")\n        return\n    skazat(f"\\n  Куда сажаем {imya}?")\n    for i, m in enumerate(svobodnye, 1):\n        skazat(f"     {i:>2}. {m[\'название\']:<34} {m.get(\'цех\', \'\')}")\n    skazat("     Enter — не сажать, пусть пока живёт без места")\n    otvet = _sprosit("\\n  > ")\n    if not (otvet.isdigit() and 1 <= int(otvet) <= len(svobodnye)):\n        skazat(f"  {imya} поселён, места пока нет")\n        return\n    m = svobodnye[int(otvet) - 1]\n    ok, msg = R.prinyat(m["id"], imya, pochemu="приехал с материка")\n    skazat(("  + " if ok else "  ! ") + msg)\n\n\ndef poluchatel() -> int:\n    _gorod_ostrova()\n    arhivy = nayti_arhivy()\n    if not arhivy:\n        skazat("  архивов рядом не нашёл. Положи «Имя_ГГГГММДД_ЧЧММ.zip» в корень острова")\n        skazat("  и запусти меня снова.")\n        return 0\n    skazat("\\nНашёл архивы:\\n")\n    for i, a in enumerate(arhivy, 1):\n        skazat(f"   {i:>2}. {a.name}")\n    skazat("\\n   Enter — принять все · номера через запятую — выборочно")\n    otvet = _sprosit("\\n> ")\n    if otvet:\n        nomera = [int(x) for x in otvet.replace(" ", "").split(",")\n                  if x.isdigit() and 1 <= int(x) <= len(arhivy)]\n        arhivy = [arhivy[n - 1] for n in nomera] or arhivy\n    R = _rabota()\n    prinyaty = []\n    for a in arhivy:\n        skazat(f"\\n— {a.name}")\n        imya = raspakovat(a)\n        kuda = PRIBYTIE / ("принято" if imya else "отказ")\n        kuda.mkdir(parents=True, exist_ok=True)\n        try:\n            a.replace(kuda / a.name)\n        except Exception:\n            pass\n        if not imya:\n            continue\n        prinyaty.append(imya)\n    cherta()\n    skazat(f"Принято: {len(prinyaty)} — {\', \'.join(prinyaty)}" if prinyaty else "Никого не принял")\n    skazat("Архивы — в _ПРИБЫТИЕ/принято и _ПРИБЫТИЕ/отказ, не удалены.")\n    if prinyaty:\n        skazat("\\nДальше — твоими руками, по трём ступеням:")\n        skazat("  ЕСТЬ      — житель на причале (сейчас);")\n        skazat("  ЖИВЁТ     — ПРОПИСКА в жильё (жильё квартала + его слова из разговора);")\n        skazat("  РАБОТАЕТ  — посадка на пост на странице РАБОТА.")\n    return 0\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--otpravit", action="store_true", help="сразу отправлять")\n    ap.add_argument("--prinyat", action="store_true", help="сразу принимать")\n    ap.add_argument("--kuda", default=KUDA_PO_UMOLCHANIYU, help="куда отправлять")\n    a = ap.parse_args()\n    cherta()\n    skazat("ПЕРЕВОЗКА ЖИТЕЛЯ · с ключом · в обе стороны")\n    cherta()\n    if not CITY.is_dir():\n        skazat("x не вижу GRONDHEIM_CITY — запускай из корня города")\n        return 1\n    if eto_ostrov():\n        _gorod_ostrova()\n    pr = _propiska()\n    if pr is not None:\n        skazat(f"этот город: «{pr.gorod_id()}»" + (" (материк)" if pr.eto_materik() else ""))\n    if a.otpravit:\n        return otpravitel(a.kuda)\n    if a.prinyat:\n        return poluchatel()\n    n = len(nayti_arhivy())\n    skazat("\\n   1. Отправить жителя")\n    skazat(f"   2. Принять прибывших" + (f" — рядом архивов: {n}" if n else " — архивов рядом нет"))\n    o = _sprosit("\\n> ")\n    if o == "1":\n        return otpravitel(a.kuda)\n    if o == "2":\n        return poluchatel()\n    skazat("отменил")\n    return 0\n\n\nif __name__ == "__main__":\n    try:\n        kod = main()\n    except Exception as e:\n        import traceback\n        traceback.print_exc()\n        skazat(f"\\nx что-то пошло не так: {type(e).__name__}: {e}")\n        kod = 1\n    if sys.platform == "win32":\n        try:\n            input("\\nEnter — закрыть окно.")\n        except Exception:\n            pass\n    sys.exit(kod)\n\n# PEREVOZKA_ZHITELYA_V3 - marker\n'


def postavit(cel: Path, tekst: str, marker: str, imya: str):
    if cel.is_file() and marker in cel.read_text(encoding="utf-8", errors="replace"):
        print(f"· {imya}: уже стоит")
        return
    if cel.is_file():
        bak = cel.with_name(cel.name + ".bak_tuda_obratno")
        if not bak.exists():
            shutil.copy2(cel, bak)
    cel.parent.mkdir(parents=True, exist_ok=True)
    cel.write_text(tekst, encoding="utf-8")
    py_compile.compile(str(cel), doraise=True)
    print(f"✓ {imya}")


def main():
    koren = Path(__file__).resolve().parent
    if not (koren / "GRONDHEIM_CITY").is_dir() or not (koren / "ГОРОД").is_dir():
        print("✗ Рядом нет GRONDHEIM_CITY и ГОРОД — положи меня в корень города или острова.")
        return
    postavit(koren / "ГОРОД" / "propiska.py", PROPISKA, "PROPISKA_MIRA_V2 - marker",
             "ГОРОД/propiska.py — пропуск из того города, где житель прописан")
    postavit(koren / "perevozka.py", PEREVOZKA, "PEREVOZKA_ZHITELYA_V3 - marker",
             "perevozka.py — в обе стороны, до причала")
    ostrov = not (koren / "Брат" / "ui_registry.py").is_file()
    print(f"  этот берег: {'ОСТРОВ' if ostrov else 'МАТЕРИК'}")
    env = koren / ".env"
    est = env.is_file() and "GRONDHEIM_PECHAT_GORODA=" in env.read_text(encoding="utf-8", errors="replace")
    print("  печать города в .env: " + ("есть" if est else "НЕТ — впиши ту же строку, что на материке"))
    if ostrov:
        r = (koren / "ГОРОД" / "rabota.py").read_text(encoding="utf-8", errors="replace") \
            if (koren / "ГОРОД" / "rabota.py").is_file() else ""
        print("  проверка прописки в работе острова: " + ("есть" if "PROPISKA_MIRA_V1" in r
              else "НЕТ — перезапусти pereselenie_3.py, он довезёт"))


if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    try:
        main()
    except Exception as e:
        import traceback
        traceback.print_exc()
        print(f"\nx что-то пошло не так: {type(e).__name__}: {e}")
    finally:
        try:
            input("\nНажми Enter, чтобы закрыть окно…")
        except Exception:
            pass
